function translateStaticDom() {
  if (activeLanguage !== 'en' || typeof document === 'undefined') return;
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes: Text[] = [];
  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
  for (const node of nodes) {
    const parent = node.parentElement;
    if (!parent || ['SCRIPT', 'STYLE', 'TEXTAREA', 'INPUT', 'CODE'].includes(parent.tagName)) continue;
    const raw = node.nodeValue ?? '', trimmed = raw.trim(), translated = translations[trimmed];
    if (translated) node.nodeValue = raw.replace(trimmed, translated);
  }
}

let domObserver: MutationObserver | null = null;
function observeStaticDom() {
  if (typeof document === 'undefined' || domObserver) return;
  domObserver = new MutationObserver(translateStaticDom);
  domObserver.observe(document.body, { childList: true, subtree: true });
  translateStaticDom();
}
export const uiLanguage = writable<UiLanguage>('fr');
let activeLanguage: UiLanguage = 'fr';
uiLanguage.subscribe((language) => { activeLanguage = language; });

/** Resolve a known UI key from the explicit French/English catalogue. */
export function t(french: string): string {
  if (activeLanguage !== 'en') return french;
  const exact = translations[french];
  if (exact) return exact;
  // UI strings often interpolate a count, a date or a selected model. Keep the
  // dynamic value while translating the known surrounding copy.
  let translated = french;
  for (const [source, target] of Object.entries(translations).sort(([a], [b]) => b.length - a.length)) {
    if (source.length >= 8 && translated.includes(source)) translated = translated.replaceAll(source, target);
  }
  return translated;
}

export function applyUiLanguage(language: UiLanguage) {
  activeLanguage = language;
  uiLanguage.set(language);
  if (typeof document !== 'undefined') {
    document.documentElement.lang = language;
    if (language === 'en') {
      observeStaticDom();
      translateStaticDom();
    }
  }
}
